<style>
.enquiry-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:22px}.enquiry-heading h2{margin:0 0 6px}.enquiry-heading p{margin:0}.enquiry-label{display:inline-block;padding:5px 10px;border-radius:20px;background:#eff6ff;color:#1d4ed8;font-size:12px;font-weight:600;white-space:nowrap}.enquiry-label.new{background:#ecfdf5;color:#047857}.enquiry-label.failed{background:#fff7ed;color:#9a3412}.enquiry-table td{vertical-align:middle}.enquiry-table small{display:block;color:#64748b;margin-top:5px}.enquiry-filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:24px}.enquiry-filters label{margin:0}.enquiry-filters select{min-width:160px}.enquiry-details{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:24px}.enquiry-message{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;margin-top:24px;border-top:1px solid #e2e8f0;padding-top:24px}.enquiry-meta{margin:0}.enquiry-meta dt{font-size:12px;font-weight:600;color:#64748b;margin-top:20px}.enquiry-meta dt:first-child{margin-top:0}.enquiry-meta dd{margin:6px 0 0;overflow-wrap:anywhere}.enquiry-empty{text-align:center;padding:36px;color:#64748b}.enquiry-recipient{font-size:13px;color:#64748b}@media(max-width:750px){.enquiry-details{grid-template-columns:1fr}.enquiry-filters label{width:100%}.enquiry-filters select{width:100%}}
</style>
